<script>
function openEpModal(id){document.getElementById(id)?.classList.add('open')}function closeEpModal(id){document.getElementById(id)?.classList.remove('open')}function filterPassports(value){const needle=value.toLocaleLowerCase('pl');document.querySelectorAll('#passport-rows tr[data-search]').forEach(row=>row.style.display=row.dataset.search.includes(needle)?'':'none')}document.querySelectorAll('.ep-modal').forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)modal.classList.remove('open')}));
@if($errors->any())openEpModal('{{old('xlsx_file') ? 'import-modal' : 'create-modal'}}');@endif
@if(request('create'))openEpModal('create-modal');@endif
</script>
